import os
import itertools
from typing import Optional
from taf.ul.parser.pcap.pcap_parser import PcapParser


class pcap(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self._pcap_parser = PcapParser()
        self._pdml_file = None

    def teardown(self):
        """
        Delete pdml file.
        """
        if self._pdml_file:
            if os.path.exists(self._pdml_file):
                os.remove(self._pdml_file)

    def load_pcap_file(self, pcap_file, tshark_path=None, luashark_path=None, command_template=None):
        # type: (str, Optional[str], Optional[str], Optional[str]) ->  list
        """
        Load packets from pcap file, it contains two steps: 1.Convert pcap to pdml. 2.Read packets from pdml file.

        :param str pcap_file: path of pcap file
        :param Optional[str] tshark_path: path of tshark executable
        :param Optional[str] luashark_path: path of luashark file
        :param Optional[str] command_template: tshark command template of pcap to pdml conversion
        :return: all packets in the pcap log with PdmlLogEntry format
        :rtype: list(generator(PdmlLogEntry))
        """
        self._pdml_file = self._pcap_parser.convert_pcap_file(pcap_file, tshark_path, luashark_path, command_template)
        pdml_entries = self._pcap_parser.read_pdml_file(self._pdml_file)
        return [pdml_entries]

    def filter_packets_by_expression(self, pdml_list, filter_expression):
        # type: (list, str) -> list
        """
        Filter packets based on the required expression. Return PDML entries meet the expression.

        :param list(generator(PdmlLogEntry)) pdml_list: a list contains only one generator
        :param str filter_expression: Wireshark filter expression
        :return: PdmlLogEntry object list after filter
        :rtype: list(generator(PdmlLogEntry))
        :raises FilterFieldError: if field name in the expression does not exist in the pcap file
        :raises FilterOperatorError: if there's unsupported operator in the filter expression
        """
        pdml_entries, copy_pdml_entries = itertools.tee(pdml_list[0])
        pdml_list[0] = copy_pdml_entries
        filter_packets = self._pcap_parser.filter_packets_by_expression(pdml_entries, filter_expression)
        return [filter_packets]

    def get_field_value_by_name(self, pdml_list, field_name, attribute_name="show"):
        # type: (list, str, Optional[str]) -> list
        """
        Get field values from the packets by the specified field name.

        :param list(generator(PdmlLogEntry)) pdml_list: a list contains only one generator
        :param str field_name: field name in a packet
        :param Optional[str] attribute_name: attribute of packet field, value can be "show", "value", or "showname", \
        default is "show". Details about the attribute can be found in https://confluence.int.net.nokia.com/display/5GRANHZ/taf.ul.parser.pcap \
        Note that "frame" related fields do not have "value" attribute
        :return: field value list
        :rtype: list
        :raises DuplicatedFieldError: if the field name occurs more than once in a packet
        """
        pdml_entries, copy_pdml_entries = itertools.tee(pdml_list[0])
        pdml_list[0] = copy_pdml_entries
        return self._pcap_parser.get_field_value_by_name(pdml_entries, field_name, attribute_name)

    def get_field_value_by_xpath(self, pdml_list, xpath, attribute_name="show"):
        # type: (list, str, Optional[str]) -> list
        """
        Return attribute values for the specified field xpath.

        :param list(generator(PdmlLogEntry)) pdml_list: a list contains only one generator
        :param str xpath: field xpath in a packet
        :param Optional[str] attribute_name: attribute of packet field, value can be "show", "value", or "showname", \
        default is "show". Details about the attribute can be found in https://confluence.int.net.nokia.com/display/5GRANHZ/taf.ul.parser.pcap \
        Note that "frame" related fields do not have "value" attribute
        :return: field value list
        :rtype: list
        """
        pdml_entries, copy_pdml_entries = itertools.tee(pdml_list[0])
        pdml_list[0] = copy_pdml_entries
        return self._pcap_parser.get_field_value_by_xpath(pdml_entries, xpath, attribute_name)
